    constructor(C _c) {
        c = _c;
    }

    function run(uint256 value, uint256 timestamp) public payable {
        require(address(this).balance >= value);

        uint256 pastBefore = c.pastBlockTime();
        bool valueReverted;
        if (value != 10 ether) {
            try c.call{value: value}() {
                valueReverted = false;
            } catch {
                valueReverted = true;
            }
