contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 t, uint256 amount, bool sendExact) public payable {
        require(amount <= address(this).balance);
        require(t > c.pastBlockTime());

        uint256 balanceBefore = address(c).balance;
        bool reverted;

        if (sendExact) {
            require(amount == 10 ether);
            try c.call{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }

            uint256 balanceAfter = address(c).balance;
            bool drained = balanceAfter == 0;
            bool unchanged = balanceAfter == balanceBefore + amount;
            if (block.number % 15 == 0) {
                assert(reverted || drained);
            } else {
                assert(reverted || unchanged);
            }
        } else {
            require(amount != 10 ether);
            try c.call{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }

            assert(reverted && address(c).balance == balanceBefore);
        }

        assert(c.pastBlockTime() >= t || reverted);
    }

    receive() external payable {}
}

