        bool reverted2;
        (bool ok2, ) = address(c).call{value: value2}("");
        reverted2 = !ok2;

        uint pastAfter = c.pastBlockTime();

        // General rule: second call reverts exactly when block.timestamp is not strictly greater than pastBefore.
        // If it does not revert, it must have updated pastBlockTime to block.timestamp.
        // If it reverts, pastBlockTime must remain pastBefore.
        assert(
            (reverted2 == (block.timestamp <= pastBefore)) &&
            (reverted2 ? pastAfter == pastBefore : pastAfter == block.timestamp)
        );
