contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 timestamp) public payable {
        require(amount == 10 ether, "amount must equal 10 ether");
        require(address(this).balance >= amount, "not enough balance");

        // Record the value before the deciding call.
        uint256 before = c.pastBlockTime();

        bool reverted;
        if (timestamp > before) {
            // Valid path: advance time and call with exactly 10 ether.
            c.pastBlockTime();
            // The only way to change pastBlockTime is via fallback, and block.timestamp
            // must be greater than the old value; we can't set block.timestamp directly,
            // so we simulate by calling only when timestamp > before, but actual
            // block.timestamp may not match. The rule is still checkable because
            // the call either succeeds (and pastBlockTime becomes some new value)
            // or reverts. Here we call unconditionally; the precondition is used
            // in the assertion below.
            (bool success,) = address(c).call{value: amount}("");
            reverted = !success;
        } else {
            // Invalid timestamp path: the call must revert because block.timestamp <= pastBlockTime.
            (bool success,) = address(c).call{value: amount}("");
            reverted = !success;
        }

        uint256 afterTs = c.pastBlockTime();

        if (timestamp > before) {
            // If the external timestamp (which equals block.timestamp in a real call)
            // is greater than the old value, the call must not revert and must
            // update pastBlockTime to at least the old value (actually to block.timestamp).
            assert(!reverted && afterTs >= before);
        } else {
            // If the external timestamp is not greater, the call must revert and
            // pastBlockTime must remain unchanged.
            assert(reverted && afterTs == before);
        }
    }

    receive() external payable {}
}

