        uint before = c.pastBlockTime();

        // Deciding call: value must be exactly 10 ether per the contract precondition.
        bool secondReverted;
        try c.fallback{value: 10 ether}() { secondReverted = false; } catch { secondReverted = true; }

        uint afterVal = c.pastBlockTime();

        // General rule: if the second call completed, then its timestamp (block.timestamp)
        // was strictly greater than the timestamp stored before it, and the stored value
        // now equals the current block.timestamp. If it reverted, the stored timestamp
        // must not have advanced.
        if (!secondReverted) {
            assert(afterVal == block.timestamp && afterVal > before);
        } else {
