contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint64 delta) public payable {
        require(address(this).balance >= 10 ether);

        // Ensure c.pastBlockTime is set to a value strictly less than the current timestamp,
        // by first requiring the timestamp delta > 0.
        // If no successful setup call existed, choose delta so it's strictly bigger than 0.
        require(delta > 0);

        // ------------------------------------------------------------------
        // Setup: make a first fallback call if possible; it either reverts or succeeds.
        // Since c.pastBlockTime starts at 0 and block.timestamp > 0, the first call
        // should succeed, but handle reverts if the block condition is odd.
        // ------------------------------------------------------------------
        bool firstReverted;
        try c.fallback{value: 10 ether}() { firstReverted = false; } catch { firstReverted = true; }

        // Read the before state.
        uint256 tsBefore = c.pastBlockTime();
        uint256 balBefore = address(c).balance;

        // We want to decide whether a fallback call succeeds when block.timestamp
        // is greater than c.pastBlockTime.  We cannot control block.timestamp,
        // but we can drive the state to a value and then make the deciding call.
        //
        // If the first call succeeded, then tsBefore == block.timestamp (since
        // success sets pastBlockTime = block.timestamp).  Then a second immediate
        // call must revert because the condition block.timestamp > pastBlockTime
        // becomes false (equal timestamps).  This gives us the revert branch of
        // the rule.  To get a success branch we need delta > 0 meaning time must
        // advance, which cannot be done within one transaction.  Therefore we
        // test the revert branch after a successful setup, and the success branch
        // when setup did not happen.
        //
        // The contract's rule is: fallback sends 10 ether, and only then updates
        // timestamp and possibly balance.  We assert the observed behavior for
        // the immediate second call.

        bool secondReverted;
        try c.fallback{value: 10 ether}() { secondReverted = false; } catch { secondReverted = true; }

        uint256 tsAfter = c.pastBlockTime();
        uint256 balAfter = address(c).balance;

        if (firstReverted) {
            // Setup call reverted, meaning even the first call failed due to
            // block.timestamp not > pastBlockTime (which starts at 0).  This is
            // essentially impossible on a real chain because block.timestamp > 0.
            // Still, if it happens, tsBefore == 0.  The second call should succeed
            // if block.timestamp > 0, which it always is on-chain. So secondReverted
            // should be false, tsAfter == block.timestamp, balAfter == balBefore + 10 ether.
            assert(!secondReverted && tsAfter == block.timestamp && balAfter == balBefore + 10 ether);
        } else {
            // Setup call succeeded, so tsBefore == block.timestamp (the timestamp
            // of the setup call).  Since block.timestamp for the second call cannot
            // be strictly greater in the same transaction, the second call must revert.
            // This is the general rule: once pastBlockTime equals the current block
            // timestamp, another fallback in the same block reverts and state is unchanged.
            assert(secondReverted && tsAfter == tsBefore && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

